const getTileImageUrl = (tileId: string): string => {
  if (!tileId) return getAssetUrl("assets/tiles/Grass.png");
  if (tileId.startsWith("data:image/") || tileId.startsWith("http://") || tileId.startsWith("https://") || tileId.startsWith("blob:")) {
    return tileId;
  }
  const cleanId = tileId.replace(/\.png$/i, "").replace(/\.jpg$/i, "").trim();
  const matched = AVAILABLE_TILES.find(t => t.toLowerCase() === cleanId.toLowerCase()) || cleanId;
  return getAssetUrl(`assets/tiles/${matched}.png`);
};

const getDefaultQuestTileId = (questName: string): string => {
  if (!questName) return "Plain L1";
  const cleanName = questName.replace(/\s+Quest$/i, "").trim().toLowerCase();
  const found = AVAILABLE_TILES.find(
    (tile) => tile.toLowerCase() === cleanName || tile.toLowerCase() === questName.toLowerCase()
  );
  return found || "Plain L1";
};

const getDefaultPortalTileId = (portalName: string): string => {
  if (!portalName) return "Planar Portal";
  const nameLower = portalName.toLowerCase();
  if (nameLower.includes("sol ring")) return "Sol Ring";
  if (nameLower.includes("planar")) return "Planar Portal";
  const found = AVAILABLE_TILES.find(
    (tile) => tile.toLowerCase() === nameLower
  );
  return found || "Planar Portal";
};

const START_HP = 10;

const getCmc = (costStr: string): number => {
  if (!costStr) return 0;
  const digitMatch = costStr.match(/^\d+/);
  const generic = digitMatch ? parseInt(digitMatch[0], 10) : 0;
  const symbols = costStr.replace(/^\d+/, "");
  return generic + symbols.length;
};

const getManaType = (tileId: string): string => {
  const tile = tileId.toLowerCase();
  if (tile.includes("plain")) return "W";
  if (tile.includes("forrest")) return "G";
  if (tile.includes("mountain")) return "R";
  if (tile.includes("swamp")) return "B";
  if (tile.includes("tower")) return "U";
  return "C";
};

const getLevel = (tileId: string): number => {
  const match = tileId.match(/(.+)\s+L(\d+)/);
  return match ? parseInt(match[2], 10) : 1;
};

const isLandSpell = (card: CardJSON): boolean => {
  if (card.type.toLowerCase() !== "spell") return false;
  if (card.target?.toLowerCase() === "land") return true;
  const name = card.name.toLowerCase();
  return name === "create land" || 
         name === "upgrade land" || 
         name === "downgrade land" || 
         name === "destroy land";
};

const isSelfCastingSpell = (card: CardJSON): boolean => {
  if (!card || card.type?.toLowerCase() !== "spell") return false;
  const name = card.name.toLowerCase();
  return name === "mana boost" || name === "vision";
};

const getCardColorKey = (card: CardJSON): "white" | "black" | "red" | "green" | "colorless" | "blue" => {
  if (!card) return "colorless";
  const c = (card.color || "").toLowerCase();
  if (c === "white" || c === "w") return "white";
  if (c === "black" || c === "b") return "black";
  if (c === "red" || c === "r") return "red";
  if (c === "green" || c === "g") return "green";
  if (c === "blue" || c === "u") return "blue";
  
  const cost = (card.manaCost || "").toUpperCase();
  if (cost.includes("W")) return "white";
  if (cost.includes("B")) return "black";
  if (cost.includes("R")) return "red";
  if (cost.includes("G")) return "green";
  if (cost.includes("U")) return "blue";

  return "colorless";
};

const renderTextWithManaSymbols = (text: string) => {
  if (!text) return null;
  const regex = /\{([a-zA-Z0-9]+)\}/g;
  const parts = [];
  let lastIndex = 0;
  let match;

  while ((match = regex.exec(text)) !== null) {
    const matchIndex = match.index;
    if (matchIndex > lastIndex) {
      parts.push(text.substring(lastIndex, matchIndex));
    }
    const symbol = match[1];
    parts.push(
      <img
        key={matchIndex}
        src={getManaDataUri(symbol)}
        alt={symbol}
        style={{
          height: "1.15em",
          width: "auto",
          verticalAlign: "-0.2em",
          margin: "0 2px",
          display: "inline-block"
        }}
      />
    );
    lastIndex = regex.lastIndex;
  }

  if (lastIndex < text.length) {
    parts.push(text.substring(lastIndex));
  }

  return parts;
};

const escapeRegExp = (str: string): string => {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
};

const highlightText = (text: string, query: string) => {
  if (!query) return text;
  const parts = text.split(new RegExp(`(${escapeRegExp(query)})`, "gi"));
  return (
    <>
      {parts.map((part, idx) => 
        part.toLowerCase() === query.toLowerCase() 
          ? <mark key={idx} style={{ background: "#ffd700", color: "#000", borderRadius: "2px", padding: "0 2px" }}>{part}</mark>
          : part
      )}
    </>
  );
};

const getPlayerCreatures = (map: MapCell[][]): { card: CardJSON; col: number; row: number }[] => {
  const list: { card: CardJSON; col: number; row: number }[] = [];
  map.forEach((col) => {
    col.forEach((cell) => {
      if (cell.ownerId === 0 && cell.occupant) {
        list.push({ card: cell.occupant, col: cell.col, row: cell.row });
      }
    });
  });
  return list;
};

const addCreatureToPlayerArmy = (player: Player, card: CardJSON): Player => {
  const currentArmy = player.armyCards ? [...player.armyCards] : [];
  if (hasStacking(card)) {
    const existingIdx = currentArmy.findIndex(c => c.name === card.name);
    if (existingIdx !== -1) {
      const existing = currentArmy[existingIdx];
      const currentPower = parseInt(existing.power || "0", 10);
      const currentToughness = parseInt(existing.toughness || "1", 10);
      const cardPower = parseInt(card.power || "0", 10);
      const cardToughness = parseInt(card.toughness || "1", 10);
      const prevCount = existing.stackCount || 1;

      currentArmy[existingIdx] = {
        ...existing,
        power: (currentPower + cardPower).toString(),
        toughness: (currentToughness + cardToughness).toString(),
        stackCount: prevCount + 1
      };
      return { ...player, armyCards: currentArmy };
    }
  }

  currentArmy.push({ ...card, stackCount: card.stackCount || 1 });
  return { ...player, armyCards: currentArmy };
};

const getArenaCardStyle = (
  totalCount: number,
  index: number,
  isHovered: boolean,
  isAttackingOrBlocking: boolean,
  isPlayer: boolean,
  isMock: boolean
) => {
  let marginRight = "0px";
  if (totalCount > 5 && index < totalCount - 1) {
    const maxContainerWidth = 1100;
    const cardWidth = 170;
    const totalUnoverlappedWidth = totalCount * cardWidth;
    if (totalUnoverlappedWidth > maxContainerWidth) {
      const neededOverlap = totalUnoverlappedWidth - maxContainerWidth;
      const perCardOverlap = Math.min(95, Math.ceil(neededOverlap / (totalCount - 1)));
      marginRight = `-${perCardOverlap}px`;
    }
  }

  let transform = "none";
  if (isHovered) {
    transform = isPlayer ? "translateY(-14px) scale(1.06)" : "translateY(14px) scale(1.06)";
  } else if (isAttackingOrBlocking) {
    transform = isPlayer ? "translateY(-18px)" : "translateY(18px)";
  }

  let zIndex = index + 10;
  if (isHovered) {
    zIndex = 300;
  } else if (isAttackingOrBlocking) {
    zIndex = 200;
  }

  return {
    position: "relative" as const,
    width: "170px",
    height: "240px",
    flexShrink: 0,
    cursor: isMock ? "pointer" : "default",
    transition: "all 0.22s cubic-bezier(0.2, 0.8, 0.2, 1)",
    marginRight,
    zIndex,
    transform,
    filter: isHovered 
      ? "drop-shadow(0 14px 28px rgba(0, 0, 0, 0.85))" 
      : isAttackingOrBlocking 
        ? "drop-shadow(0 8px 20px rgba(0, 0, 0, 0.6))" 
        : "none",
  };
};

const getEnemyCreatures = (map: MapCell[][]): { card: CardJSON; col: number; row: number }[] => {
  const list: { card: CardJSON; col: number; row: number }[] = [];
  map.forEach((col) => {
    col.forEach((cell) => {
      if (cell.ownerId === 1 && cell.occupant) {
        list.push({ card: cell.occupant, col: cell.col, row: cell.row });
      }
    });
  });
  return list;
};

const getLandColorClass = (manaType: string): string => {
  if (manaType === "W") return "white";
  if (manaType === "U") return "blue";
  if (manaType === "B") return "black";
  if (manaType === "R") return "red";
  if (manaType === "G") return "green";
  return "artifact";
};

const getManaName = (manaType: string): string => {
  if (manaType === "W") return "White";
  if (manaType === "U") return "Blue";
  if (manaType === "B") return "Black";
  if (manaType === "R") return "Red";
  if (manaType === "G") return "Green";
  return "Colorless";
};

const getLandCardJson = (land: GroupedLand, map: MapCell[][]): CardJSON => {
  const singleProd = getLevel(land.tileId);
  const totalProd = singleProd * land.cells.length;
  const totalMapLands = map.flat().filter(cell => cell.tileId === land.tileId).length;
  
  return {
    name: land.tileId,
    manaCost: land.manaType,
    type: "Territory",
    color: getLandColorClass(land.manaType) as any,
    illustration: land.tileId.startsWith("data:image/") ? land.tileId : `/assets/tiles/${land.tileId}.png`,
    rulesText: `Each produces ${singleProd} {${land.manaType}} per turn.\n\nTotal: ${totalProd} {${land.manaType}}\n\nYou own ${land.cells.length}/${totalMapLands}`,
  };
};

const getCellCardJson = (cell: MapCell, map: MapCell[][], players: Player[]): CardJSON => {
  const isTower = cell.tileId.toLowerCase().includes("tower");
  const START_HP = 20; // Match the starting tower HP
  if (isTower && cell.ownerId !== null) {
    const p = players[cell.ownerId];
    const isPlayer = cell.ownerId === 0;
    const towerLevel = getLevel(cell.tileId);
    const coords = `(${cell.col}, ${cell.row})`;
    if (isPlayer) {
      const rawName = `Wizards Tower L${towerLevel}`;
      const isMatchingTower = (c: CardJSON) => {
        const typeLower = (c.type || "").toLowerCase();
        const nameLower = (c.name || "").toLowerCase();
        if (typeLower !== "tower" && !nameLower.includes("wizards tower")) return false;
        return getTowerLevelFromCard(c) === towerLevel;
      };
      const found = p.deck?.find(isMatchingTower);
      const towerCard: CardJSON = found ? JSON.parse(JSON.stringify(found)) : {
        name: "Wizards Tower",
        cardSubType: `Level ${towerLevel}`,
        manaCost: "",
        type: "Tower",
        color: "artifact",
        illustration: `/assets/towers/Wizards Tower L${towerLevel}.jpg`,
        rulesText: "",
        customDescription: "",
        power: "0",
        toughness: String(5 + 5 * towerLevel),
        activatedAbilities: [
          {
            cost: [towerLevel === 1 ? "C3" : towerLevel === 2 ? "C2" : towerLevel === 3 ? "C3" : "C1"],
            text: towerLevel === 3 ? "Draw 2 cards." : "Draw 1 card."
          }
        ]
      };
      towerCard.name = "Wizards Tower";
      towerCard.cardSubType = `Level ${towerLevel}`;
      towerCard.illustration = `/assets/towers/Wizards Tower L${towerLevel}.jpg`;
      towerCard.customDescription = "";
      if (towerCard.power === undefined) towerCard.power = "0";
      if (towerCard.toughness === undefined) towerCard.toughness = String(5 + 5 * towerLevel);
      towerCard.rulesText = `Location: ${coords}\nHP: ${p.towerHp} / ${START_HP}`;
      return towerCard;
    } else {
      return {
        name: `Sauron's Fortress L${towerLevel}`,
        manaCost: "",
        type: "Legendary Structure",
        color: "artifact",
        illustration: `/assets/tiles/Sauron's Fortress L${towerLevel}.png`,
        rulesText: `Enemy base. Deploy adjacent units to attack it.\nLevel: ${towerLevel}\n\nHP: ${p.towerHp} / ${START_HP}\nLocation: ${coords}\n\nDestroy it to win!`,
      };
    }
  }

  const singleProd = getLevel(cell.tileId);
  const manaType = getManaType(cell.tileId);
  const manaName = getManaName(manaType);
  
  const matchingCells: { col: number; row: number }[] = [];
  map.forEach((col) => {
    col.forEach((c) => {
      if (c.tileId === cell.tileId && c.ownerId === cell.ownerId) {
        matchingCells.push({ col: c.col, row: c.row });
      }
    });
  });
  
  const totalProd = singleProd * matchingCells.length;
  
  let ownerName = "Unowned";
  if (cell.ownerId === 0) ownerName = "Player 1 (You)";
  if (cell.ownerId === 1) ownerName = "Player 2 (AI)";
  
  return {
    name: cell.tileId,
    manaCost: manaType,
    type: `Territory (${ownerName})`,
    color: getLandColorClass(manaType) as any,
    illustration: cell.tileId.startsWith("data:image/") ? cell.tileId : `/assets/tiles/${cell.tileId}.png`,
    rulesText: `Each cell of this type produces ${singleProd} ${manaName} mana per turn for its owner.\n\nTotal controlled cell(s) of this type: ${matchingCells.length} (generating ${totalProd} ${manaName} mana per turn).\n\nCoordinates: ${matchingCells.map(c => `(${c.col},${c.row})`).join(", ")}`,
  };
};

const isCardColorCompatibleWithLand = (card: CardJSON, landManaType: string): boolean => {
  const color = card.color.toLowerCase();
  if (color === "artifact") return true; // Artifacts can be placed anywhere
  
  if (color === "white" && landManaType === "W") return true;
  if (color === "blue" && landManaType === "U") return true;
  if (color === "black" && landManaType === "B") return true;
  if (color === "red" && landManaType === "R") return true;
  if (color === "green" && landManaType === "G") return true;

  if (color === "gold") {
    const symbols = card.manaCost.replace(/^\d+/, "");
    return symbols.includes(landManaType);
  }

  return false;
};

const isTowerOrAbilityCard = (card: CardJSON): boolean => {
  const nameLower = card.name.toLowerCase();
  const typeLower = card.type.toLowerCase();
  const subTypeLower = (card.cardSubType || "").toLowerCase();
  return (
    typeLower.includes("tower") ||
    nameLower.includes("tower") ||
    nameLower.endsWith("ability") ||
    nameLower.includes("ability") ||
    typeLower.includes("ability") ||
    subTypeLower.includes("ability")
  );
};

const isSpecialCard = (card: CardJSON | null | undefined): boolean => {
  if (!card) return false;
  const nameLower = (card.name || "").toLowerCase();
  const isPlayerWizard = isWizardCard(card) || nameLower === "ultimate victory";
  return isPlayerWizard || nameLower.endsWith("ability");
};

const isHeroCard = (card: CardJSON | null | undefined): boolean => {
  if (!card) return false;
  const typeLower = (card.type || "").toLowerCase();
  const subTypeLower = (card.cardSubType || "").toLowerCase();
  return (typeLower.includes("hero") || subTypeLower.includes("hero")) && !typeLower.includes("quest");
};

const isLegendCard = (card: CardJSON | null | undefined): boolean => {
  if (!card) return false;
  const typeLower = (card.type || "").toLowerCase();
  const subTypeLower = (card.cardSubType || "").toLowerCase();
  return (typeLower.includes("legend") || subTypeLower.includes("legend")) && !typeLower.includes("quest");
};

const isArtifactCard = (card: CardJSON | null | undefined): boolean => {
  if (!card) return false;
  const typeLower = (card.type || "").toLowerCase();
  const subTypeLower = (card.cardSubType || "").toLowerCase();
  if (typeLower.includes("tower") || typeLower.includes("wizard") || isSpecialCard(card)) {
    return false;
  }
  return typeLower.includes("artifact") || subTypeLower.includes("artifact");
};

const isPortalCard = (card: CardJSON | null | undefined): boolean => {
  if (!card) return false;
  const typeLower = (card.type || "").toLowerCase();
  const subTypeLower = (card.cardSubType || "").toLowerCase();
  return typeLower.includes("portal") || subTypeLower.includes("portal");
};

interface GroupedLand {
  tileId: string;
  manaType: string;
  cells: { col: number; row: number }[];
}

const COLOR_ORDER: Record<string, number> = { U: 1, W: 2, B: 3, R: 4, G: 5 };

const ARTIFACT_BUFFS: Record<string, { power: number; toughness: number; desc: string }> = {
  "bracelet of strength": { power: 0, toughness: 0, desc: "+0/+0" },
  "poisoned dagger": { power: 0, toughness: 0, desc: "Grants Poison" },
  "poisined dagger": { power: 0, toughness: 0, desc: "Grants Poison" },
  "ring of power": { power: 0, toughness: 0, desc: "+0/+0" },
  "ringmail of protection": { power: 0, toughness: 0, desc: "+0/+0" },
  "scepter of doom": { power: 0, toughness: 0, desc: "+0/+0" },
  "sword of glory": { power: 0, toughness: 0, desc: "+0/+0" },
  "battlewand": { power: 0, toughness: 0, desc: "+0/+0" },
  "boots of luck": { power: 0, toughness: 0, desc: "+0/+0" },
  "dragonshield": { power: 0, toughness: 0, desc: "+0/+0" },
  "gauntlet of might": { power: 0, toughness: 0, desc: "+0/+0" }
};

const getGroupedLands = (map: MapCell[][]): GroupedLand[] => {
  const groups: Record<string, GroupedLand> = {};
  map.forEach((col) => {
    col.forEach((cell) => {
      if (cell.ownerId === 0) {
        if (!groups[cell.tileId]) {
          groups[cell.tileId] = {
            tileId: cell.tileId,
            manaType: getManaType(cell.tileId),
            cells: [],
          };
        }
        groups[cell.tileId].cells.push({ col: cell.col, row: cell.row });
      }
    });
  });
  
  return Object.values(groups).sort((a, b) => {
    const orderA = COLOR_ORDER[a.manaType] || 99;
    const orderB = COLOR_ORDER[b.manaType] || 99;
    if (orderA !== orderB) {
      return orderA - orderB;
    }
    return getLevel(a.tileId) - getLevel(b.tileId);
  });
};

const getOwnedLandsCount = (map: MapCell[][]): number => {
  let count = 0;
  map.forEach((col) => {
    col.forEach((cell) => {
      if (cell.ownerId === 0) {
        count++;
      }
    });
  });
  return count;
};

