const getSpellIconClass = (color?: string): string => {
  if (color === "red") return "fa-fire";
  if (color === "blue") return "fa-droplet";
  if (color === "green") return "fa-leaf";
  if (color === "black") return "fa-skull";
  return "fa-sun";
};

const getSpellColorHex = (color?: string): string => {
  if (color === "red") return "#ff3366";
  if (color === "blue") return "#38bdf8";
  if (color === "green") return "#4ade80";
  if (color === "black") return "#a855f7";
  return "#facc15";
};

const getSpellColorBg = (color?: string): string => {
  if (color === "red") return "rgba(255, 51, 102, 0.18)";
  if (color === "blue") return "rgba(56, 189, 248, 0.18)";
  if (color === "green") return "rgba(74, 222, 128, 0.18)";
  if (color === "black") return "rgba(168, 85, 247, 0.18)";
  return "rgba(250, 204, 21, 0.18)";
};

const parseSpellManaSymbols = (costStr?: string): string[] => {
  if (!costStr) return [];
  const cleaned = costStr.replace(/C(\d+)/g, "$1");
  const bracedMatches = Array.from(cleaned.matchAll(/\{([^}]+)\}/g)).map(m => m[1]);
  if (bracedMatches.length > 0) return bracedMatches;
  const matches: string[] = [];
  const digitMatch = cleaned.match(/^(\d+)/);
  if (digitMatch) matches.push(digitMatch[1]);
  const symbols = cleaned.replace(/^\d+/, "");
  for (const char of symbols) matches.push(char);
  return matches;
};

const canPlayerAffordManaCost = (
  manaPool: { W: number; U: number; B: number; R: number; G: number; C: number } | undefined,
  manaCostStr?: string
): boolean => {
  if (!manaCostStr) return true;
  const pool = { ...(manaPool || { W: 0, U: 0, B: 0, R: 0, G: 0, C: 0 }) };
  const symbols = parseSpellManaSymbols(manaCostStr);
  if (symbols.length === 0) return true;

  let genericCost = 0;
  const coloredNeeded: ("W" | "U" | "B" | "R" | "G" | "C")[] = [];

  for (const sym of symbols) {
    const num = parseInt(sym, 10);
    if (!isNaN(num)) {
      genericCost += num;
    } else {
      const upper = sym.toUpperCase() as "W" | "U" | "B" | "R" | "G" | "C";
      if (["W", "U", "B", "R", "G", "C"].includes(upper)) {
        coloredNeeded.push(upper);
      }
    }
  }

  for (const col of coloredNeeded) {
    if ((pool[col] || 0) > 0) {
      pool[col]--;
    } else {
      return false;
    }
  }

  const totalRemainingPool = Object.values(pool).reduce((a, b) => a + b, 0);
  return totalRemainingPool >= genericCost;
};

const renderPlayerManaPoolBadge = (player: Player, customName?: string) => {
  const pool = player.manaPool || { W: 0, U: 0, B: 0, R: 0, G: 0, C: 0 };
  const manaTypes = ["W", "B", "R", "G", "C"] as const;
  const totalMana = Object.values(pool).reduce((a, b) => a + b, 0);
  const displayName = customName || player.name;

  return (
    <div
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: "6px",
        background: "rgba(15, 23, 42, 0.75)",
        border: "1px solid rgba(255, 255, 255, 0.15)",
        borderRadius: "20px",
        padding: "3px 10px",
        boxShadow: "0 2px 8px rgba(0, 0, 0, 0.4)",
        textTransform: "none",
        letterSpacing: "normal",
        fontWeight: "normal"
      }}
      title={`${displayName}'s Available Mana Pool (Total: ${totalMana})`}
    >
      <span style={{ fontSize: "0.72rem", color: "var(--text-muted)", fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.5px", marginRight: "2px" }}>
        Mana:
      </span>
      {manaTypes.map((type) => {
        const amount = pool[type] || 0;
        return (
          <div
            key={type}
            style={{
              display: "flex",
              alignItems: "center",
              gap: "3px",
              opacity: amount > 0 ? 1 : 0.35,
              filter: amount > 0 ? "none" : "grayscale(80%)",
              transition: "opacity 0.2s ease"
            }}
          >
            <img
              src={getManaDataUri(type)}
              alt={type}
              style={{ width: "15px", height: "15px", display: "block" }}
            />
            <span style={{ fontSize: "0.75rem", fontWeight: "800", color: amount > 0 ? "#fff" : "rgba(255, 255, 255, 0.5)", minWidth: "8px" }}>
              {amount}
            </span>
          </div>
        );
      })}
    </div>
  );
};

const resolveQuestRewardCards = (levelObj: QuestLevelJSON | undefined, cardPool: CardJSON[], activeColors: string[]): CardJSON[] => {
  if (!levelObj || !hasCardReward(levelObj)) {
    return [];
  }
  const grant = resolveCardGrantForLevel(levelObj, cardPool);
  if (grant.isChoice) {
    return []; // Handled via choice modal
  }
  if (grant.cardsToGrant && grant.cardsToGrant.length > 0) {
    return grant.cardsToGrant;
  }
  return grant.cardToGrant ? [grant.cardToGrant] : [];
};

const resolveQuestRewardCard = (levelObj: QuestLevelJSON | undefined, cardPool: CardJSON[], activeColors: string[]): CardJSON | null => {
  const cards = resolveQuestRewardCards(levelObj, cardPool, activeColors);
  return cards.length > 0 ? cards[0] : null;
};

const getQuestLevelOccupant = (levelObj: QuestLevelJSON | undefined, cardPool: CardJSON[]): CardJSON | null => {
  if (!levelObj) return null;
  
  let opponentsList: CardJSON[] = [];
  if (levelObj.opponents && levelObj.opponents.length > 0) {
    opponentsList = levelObj.opponents.map((ref: string) => resolveOpponentCard(ref, cardPool)).filter(Boolean);
  } else {
    opponentsList = generateQuestOpponents(levelObj, cardPool);
  }
  
  if (opponentsList.length === 0) return null;

  let highestPowerCreature = opponentsList[0];
  if (opponentsList.length > 1) {
    opponentsList.forEach(c => {
      const pCurr = parseInt(highestPowerCreature.power || "0", 10) || 0;
      const pNext = parseInt(c.power || "0", 10) || 0;
      if (pNext > pCurr) {
        highestPowerCreature = c;
      }
    });
  }

  const occupant = JSON.parse(JSON.stringify(highestPowerCreature));
  occupant.questArmy = opponentsList;
  return occupant;
};

export { cardNameMap, mapCardJson };

export const getQuestMapFromDeckJson = (json: any): Record<string, any> => {
  const questMap: Record<string, any> = {};
  if (json && json.quests && Array.isArray(json.quests)) {
    json.quests.forEach((q: any) => {
      const k1 = q.id || q.cardId || q.name;
      const k2 = q.name;
      if (k1) questMap[k1] = q;
      if (k2) questMap[k2] = q;
    });
  }
  return questMap;
};

export const resolveQuestData = (questCard: CardJSON | null | undefined, cardPool: CardJSON[] = []): QuestDataJSON | undefined => {
  if (!questCard) return undefined;
  if (questCard.questData) return questCard.questData;
  const foundInPool = cardPool.find(c => c.name === questCard.name && c.questData);
  if (foundInPool?.questData) return foundInPool.questData;
  const isTowerOfTerror = (questCard.name || "").toLowerCase().includes("tower of terror");
  if (isTowerOfTerror) return defaultTowerOfTerrorQuestData;
  return undefined;
};

