  useEffect(() => {
    localStorage.setItem("wizards_high_scores", JSON.stringify(highScores));
  }, [highScores]);

  const getCompletedLandSetsCount = (mapCells?: MapCell[][]): number => {
    if (!mapCells) return 0;
    const flat = mapCells.flat();
    const grouped: Record<string, { owned: number; total: number }> = {};

    flat.forEach((cell) => {
      const baseName = cell.tileId.replace(/\s+L\d+/i, "").trim();
      if (!grouped[baseName]) grouped[baseName] = { owned: 0, total: 0 };
      grouped[baseName].total++;
      if (cell.ownerId === 0) {
        grouped[baseName].owned++;
      }
    });

    let count = 0;
    Object.values(grouped).forEach(({ owned, total }) => {
      if (total > 0 && owned === total) {
        count++;
      }
    });
    return count;
  };

  const calculateGameScore = (
    isVictory: boolean,
    xp: number,
    landsCount: number,
    towerHp: number,
    turns: number,
    rewardsCount: number = 0,
    isEndGame: boolean = false,
    completedSetsCount: number = 0
  ): number => {
    const xpPoints = Math.max(0, xp);
    const landPoints = landsCount * 50;
    const questPoints = rewardsCount * 200;

    if (!isEndGame) {
      return xpPoints + landPoints + questPoints;
    }

    const towerPoints = Math.max(0, towerHp) * 100;
    const turnBonus = Math.max(0, (100 - turns) * 10);
    const victoryBonus = isVictory ? 1500 : 0;
    const landSetBonus = completedSetsCount * 500;

    return xpPoints + landPoints + questPoints + towerPoints + turnBonus + victoryBonus + landSetBonus;
  };
