  const handleSaveGame = () => {
    if (!gameState) return;
    const savePayload = {
      version: 1,
      timestamp: Date.now(),
      gameState,
      questRewardsHistory,
      customDeckFileName,
      customMapFileName,
      p1DeckColors,
    };
    const jsonStr = JSON.stringify(savePayload, null, 2);

    try {
      localStorage.setItem("wizards_quicksave", jsonStr);
    } catch (e) {
      console.warn("LocalStorage quota exceeded for quicksave", e);
    }

    const blob = new Blob([jsonStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `wizards_savegame_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);

    addLog("💾 Game state saved successfully!");
  };

