                          setGameState(prev => {
                            if (!prev) return null;
                            const newPlayers = [...prev.players];
                            const p = { ...newPlayers[prev.activePlayerIndex] };
                            const current = p.manaPool || { W: 0, U: 0, B: 0, R: 0, G: 0, C: 0 };
                            p.manaPool = {
                              W: current.W + 10,
                              U: current.U + 10,
                              B: current.B + 10,
                              R: current.R + 10,
                              G: current.G + 10,
                              C: current.C + 10,
                            };
                            newPlayers[prev.activePlayerIndex] = p;
                            return { ...prev, players: newPlayers };
                          });
                          addLog("🧪 Added +10 test mana of all colors!");
