                const totalCount = uniqueNames.size;
                const activeCount = Array.from(uniqueNames).filter(name => !disabledCardNames.includes(name)).length;

                return <h2 style={{ margin: 0 }}>Player Library Quests ({activeCount} / {totalCount} Unique Quests)</h2>;
