              const player0 = gameState.players[0];
              const landsCount = gameState.map ? gameState.map.flat().filter(cell => cell.ownerId === 0).length : 0;
              const xp = player0?.xp || 0;
              const questsCount = questRewardsHistory.length;
              const turnNum = gameState.turnNumber || 1;
              const towerHp = player0?.towerHp || 0;

              const landPts = landsCount * 50;
              const questPts = questsCount * 200;
              const xpPts = Math.max(0, xp);
              const currentLiveScore = landPts + questPts + xpPts;

              const completedSets = getCompletedLandSetsCount(gameState.map);
              const landSetBonus = completedSets * 500;
              const projectedTurnBonus = Math.max(0, (100 - turnNum) * 10);
              const projectedTowerPts = Math.max(0, towerHp) * 100;
              const victoryBonus = 1500;
              const projectedFinalScore = currentLiveScore + projectedTurnBonus + projectedTowerPts + victoryBonus + landSetBonus;

