                      padding: "6px 12px",
                      fontSize: "0.85rem",
                      fontWeight: "bold",
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      gap: "6px",
                      fontFamily: "Outfit, sans-serif",
                      transition: "transform 0.1s ease"
