                  zIndex: 250,
                  background: "rgba(11, 20, 38, 0.96)",
                  border: "1px solid rgba(0, 240, 255, 0.35)",
                  borderRadius: "12px",
                  padding: "12px",
                  display: "flex",
                  flexDirection: "column",
                  gap: "8px",
                  boxShadow: "0 10px 30px rgba(0,0,0,0.75), 0 0 20px rgba(0, 240, 255, 0.2)",
                  backdropFilter: "blur(12px)"
